{
  "echo": "38bd0fddd65d",
  "circuit": {
    "name": "5t-ota",
    "devices": [
      {"id": "M1", "kind": "nmos", "nodes": ["n1", "inp", "ntail", "0"], "params": {"W": "120u", "L": "0.8u"}},
      {"id": "M2", "kind": "nmos", "nodes": ["out", "inn", "ntail", "0"], "params": {"W": "120u", "L": "0.8u"}},
      {"id": "M3", "kind": "pmos", "nodes": ["n1", "n1", "vdd", "vdd"], "params": {"W": "30u", "L": "1u"}},
      {"id": "M4", "kind": "pmos", "nodes": ["out", "n1", "vdd", "vdd"], "params": {"W": "30u", "L": "1u"}},
      {"id": "M5", "kind": "nmos", "nodes": ["ntail", "nbias", "0", "0"], "params": {"W": "15u", "L": "1u"}}
    ]
  },
  "vbias": 0.95,
  "rationale": "High gm/Id (~19) input pair 120u/0.8u gives gm~0.75mS, so GBW~24MHz into 5pF. Mirror pole near 150MHz keeps PM>80. Long L (0.8u/1u) raises ro for ~45dB gain. M5 15u/1u at vbias 0.95V sets tail ~80uA, inside the 100uA budget."
}
